using System;using System.IO;using System.Collections;using System.Collections.Generic;using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;
namespace Wuxia {
 // Optional command-line capture runner for this project's own native player.
 public class PreviewCapture:MonoBehaviour {
  string folder;WuxiaGame game;int errors;float minFps=999;int samples;double totalFrame;
  [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]
  static void Boot(){foreach(var arg in Environment.GetCommandLineArgs())if(arg.StartsWith("--wuxia-capture=")){var game=FindFirstObjectByType<WuxiaGame>();var capture=game.gameObject.AddComponent<PreviewCapture>();capture.folder=arg.Substring("--wuxia-capture=".Length);}}
  IEnumerator Start(){if(string.IsNullOrEmpty(folder))yield break;Directory.CreateDirectory(folder);game=GetComponent<WuxiaGame>();game.skipSimulation=true;Application.logMessageReceived+=Log;Screen.SetResolution(1280,720,FullScreenMode.Windowed);yield return new WaitForSecondsRealtime(1);yield return Save("01-menu");game.ShowStory();yield return Save("02-story");game.StartStory();yield return Save("03-guide");game.FinishGuide();for(int i=0;i<100;i++){game.Step(1/60f,new InputFrame{move=1,jump=i==30,jumpHeld=true});yield return null;}yield return Save("04-story-play");game.StartTraining();game.FinishGuide();game.player.Place(550,620);game.invincibleUntil=10000;for(int i=0;i<90;i++){game.Step(1/60f,default);yield return null;}yield return Save("04b-enemies");game.StartFinal();game.FinishGuide();game.player.Place(420,620);game.invincibleUntil=10000;for(int i=0;i<180;i++){game.Step(1/60f,default);yield return null;}game.Step(1/60f,new InputFrame{ward=true});for(int i=0;i<20;i++){game.Step(1/60f,default);yield return null;}yield return Save("05-formation");game.ChangeBoss("novaTell",3);for(int i=0;i<155;i++){game.Step(1/60f,default);yield return null;}yield return Save("06-master-warning");for(int i=0;i<40;i++){game.Step(1/60f,default);yield return null;}yield return Save("07-master-surge");game.StartEndless();game.FinishGuide();foreach(var e in game.enemies)e.hp=0;game.FinishWave();for(int i=0;i<275;i++){game.Step(1/60f,new InputFrame{move=1});yield return null;}yield return null;Canvas.ForceUpdateCanvases();float beforeHp=game.hp,beforeMax=game.MaxHP;Click("机缘 · "+game.offers[0]);Click("机缘 · "+game.offers[1]);Click("机缘 · heal");Verify(game.pendingUpgrade=="heal"&&game.hp==beforeHp&&game.MaxHP==beforeMax,"鼠标射线命中卡面、改选三次且未提前生效");yield return Save("08-cards");Click("确认 · 进入下一步");Verify(game.phase==GamePhase.Play,"原生确认按钮触发回春丹并开始下一波");game.run.wave=4;game.BeginWave();game.boss.dir=-1;game.boss.Place(1000,620);game.ChangeBoss("charge",3);game.boss.targetX=450;for(int i=0;i<75;i++){game.Step(1/60f,default);yield return null;}yield return Save("09-stone-platforms");game.run.wave=4;game.BeginWave();game.player.Place(770,620);game.boss.Place(1000,620);game.ChangeBoss("slamTell",.05f);for(int i=0;i<28;i++){game.Step(1/60f,default);yield return null;}yield return Save("09b-ground-quake");game.StartEndless();game.FinishGuide();yield return Save("09c-symmetric-platforms");foreach(var upgrade in game.data.upgrades)if(upgrade.id!="heal")game.hp=Rules.Apply(game.data,game.run,upgrade.id,game.hp);game.ui.Refresh();yield return Save("09d-compact-talents");yield return AnimationChecks();game.ShowMenu();yield return Save("10-return-menu");game.StartEndless();game.FinishGuide();game.invincibleUntil=10000;game.skipSimulation=false;game.automatedPlayback=true;var liveFrames=new List<float>();for(int i=0;i<240;i++){game.playbackInput=new InputFrame{move=i/40%2==0?1:-1,attack=i%50>30,jump=i==50||i==130,jumpHeld=true,ward=i==75,ranged=i==185};yield return null;if(i>30)liveFrames.Add(Time.unscaledDeltaTime*1000);}game.playbackInput=default;yield return Save("11-live-physics-render");game.ShowMenu();yield return null;game.StartTraining();game.FinishGuide();yield return null;game.ShowMenu();yield return null;liveFrames.Sort();File.WriteAllText(Path.Combine(folder,"live-run-validation.txt"),$@"Actual Update + FixedUpdate + LateUpdate, 240 frames
Direction changes, jumping, melee and swords, home/restart: completed
P50 frame ms: {liveFrames[liveFrames.Count/2]:0.00}
P95 frame ms: {liveFrames[Mathf.FloorToInt(liveFrames.Count*.95f)]:0.00}
Errors so far: {errors}
");game.automatedPlayback=false;game.skipSimulation=true;Application.logMessageReceived-=Log;File.WriteAllText(Path.Combine(folder,"player-validation.txt"),$"Unity {Application.unityVersion}\nNative player rendering and UGUI: completed\nRuntime errors: {errors}\nFrames: {samples}\nAverage frame time (scripted capture): {(samples>0?totalFrame/samples*1000:0):0.00} ms\n");Application.Quit(errors==0?0:1);}
  IEnumerator AnimationChecks(){
   game.StartTraining();game.FinishGuide();game.invincibleUntil=10000;game.boss.hp=0;game.boss.Disable();foreach(var e in game.enemies){e.hp=0;e.Disable();}game.invincibleUntil=-1;game.player.Place(400,620);for(int i=0;i<8;i++)game.Step(1/60f,default);game.facing=1;game.RenderActors();yield return Save("12-waist-right");game.facing=-1;game.RenderActors();yield return Save("12b-waist-left");game.facing=1;for(int i=0;i<8;i++){for(int j=0;j<6;j++)game.Step(1/60f,new InputFrame{move=1});yield return Save("13-run-"+i);}
   game.player.Place(500,620);for(int i=0;i<8;i++)game.Step(1/60f,default);game.Step(1/60f,new InputFrame{dash=true,move=1});yield return Save("13b-dash-start");for(int i=0;i<16;i++)game.Step(1/60f,default);yield return Save("13c-dash-end");
   game.StartStory();game.FinishGuide();foreach(var e in game.enemies){e.hp=0;e.Disable();}var ledge=game.platforms.Find(p=>p.data.y<620);game.player.Place(ledge.data.x+ledge.data.w*.5f,ledge.data.y+ledge.data.h+game.player.TerrainHeight+2);game.player.VY=-740;Physics2D.SyncTransforms();for(int i=0;i<2;i++)game.Step(1/60f,new InputFrame{jumpHeld=true});Verify(game.player.Feet-game.player.TerrainHeight>=ledge.data.y+ledge.data.h-1.5f,"原生剧情跳跃头部不会进入高台");yield return Save("13d-head-under-platform");
   game.StartTraining();game.FinishGuide();game.boss.hp=0;game.boss.Disable();foreach(var e in game.enemies){e.hp=0;e.Disable();}
   game.player.Place(500,620);for(int i=0;i<6;i++)game.Step(1/60f,default);for(int i=0;i<9;i++)game.Step(1/60f,new InputFrame{jump=i==0,jumpHeld=true,attack=true});yield return Save("14-jump-slash");
   foreach(int dir in new[]{-1,1}){game.StartTraining();game.FinishGuide();game.invincibleUntil=10000;game.player.Place(780,620);game.boss.Place(1000,620);game.boss.active=true;game.boss.dir=dir;game.boss.targetX=1000+dir*220;game.ChangeBoss("charge",2);for(int i=0;i<12;i++)game.Step(1/60f,default);Verify(game.boss.view.renderer.flipX==(dir>0)&&Mathf.Sign(game.boss.VX)==dir,"石像面朝行进方向 "+dir);yield return Save("15-charge-"+(dir<0?"left":"right"));}
   game.StartEndless();game.FinishGuide();game.invincibleUntil=10000;game.player.Place(580,620);foreach(var e in game.enemies)e.hp=e.maxHp=100;game.hp=Rules.Apply(game.data,game.run,"frost",game.hp);game.run.nextFrost=game.clock+.05f;for(int i=0;i<12;i++)game.Step(1/60f,default);yield return Save("16-frost-crystals");
   game.StartFinal();game.FinishGuide();game.invincibleUntil=10000;game.player.Place(500,620);game.boss.active=true;game.ChangeBoss("recover",100);for(int i=0;i<43;i++)game.Step(1/60f,new InputFrame{ranged=i==0});Verify(game.boss.hp<game.boss.maxHp,"实际飞剑命中首领并扣血");yield return Save("17-flying-sword-impact");
  }
  IEnumerator Save(string name){if(game.player!=null)File.AppendAllText(Path.Combine(folder,"positions.txt"),name+" player="+game.player.X+","+game.player.Feet+" camera="+game.gameCamera.transform.position+" boss="+(game.boss!=null?game.boss.X+","+game.boss.Feet+" view="+game.boss.view.root.transform.position+" scale="+game.boss.view.root.transform.localScale:"none")+"\n");game.ui.FitScreen();game.ui.Refresh();yield return null;yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.Combine(folder,name+".png"));yield return new WaitForSecondsRealtime(.3f);}
  void Verify(bool ok,string description){File.AppendAllText(Path.Combine(folder,"pointer-validation.txt"),(ok?"PASS: ":"FAIL: ")+description+"\n");if(!ok){Debug.LogError(description);Application.Quit(1);}}
  void Click(string name){var button=Array.Find(game.ui.GetComponentsInChildren<Button>(true),b=>b.name==name&&b.gameObject.activeInHierarchy);if(!button){Verify(false,"找不到按钮 "+name);return;}var corners=new Vector3[4];button.GetComponent<RectTransform>().GetWorldCorners(corners);var pointer=new PointerEventData(EventSystem.current){position=(corners[0]+corners[2])*.5f,button=PointerEventData.InputButton.Left};var results=new List<RaycastResult>();EventSystem.current.RaycastAll(pointer,results);if(results.Count==0){Verify(false,"鼠标射线未命中 "+name);return;}ExecuteEvents.ExecuteHierarchy(results[0].gameObject,pointer,ExecuteEvents.pointerClickHandler);}
  void Update(){if(folder==null)return;if(Time.unscaledDeltaTime>0){samples++;totalFrame+=Time.unscaledDeltaTime;minFps=Mathf.Min(minFps,1/Time.unscaledDeltaTime);}}
  void Log(string condition,string stack,LogType type){if(type==LogType.Exception||type==LogType.Error)errors++;}
 }
}
